const settings = $input.first().json;
const sectors = String(settings.sectors || '')
  .split(',')
  .map((sector) => sector.trim())
  .filter(Boolean);

if (sectors.length === 0) {
  throw new Error('Funding tracker settings has no sectors. Put at least one sector in sectors, separated by commas.');
}

return sectors.map((sector) => ({
  json: {
    sector,
    stages: settings.stages,
    minAmountUsd: settings.minAmountUsd,
    lookbackDays: settings.lookbackDays,
    articleCount: settings.articleCount,
  },
}));

parameters.text:
=You are tracking startup funding rounds in one sector: {{ $json.sector }}

Call the Webz.io news search tool exactly once, with these arguments:

- query: startup raises funding round {{ $json.stages }} {{ $json.sector }}
- days: {{ $json.lookbackDays }}
- language: ["english"]
- k: {{ $json.articleCount }}

Do not pass any other filters.

From what the tool returns, extract every announced, completed venture funding round in this sector. Include seed, Series A/B/C, growth, and strategic equity rounds that match the stages filter when possible.

Exclude rumors, "in talks" or "seeking" stories, IPOs, debt and loans, grants, and roundup listicles that mention many companies without a dedicated announcement.

For each round return company, round_type, amount_usd (0 if not disclosed), lead_investors, company_description, headline, publisher, announced date, and url. Set sector to {{ $json.sector }}.

If nothing qualifies, return an empty rounds array.

