const settings = $('Funding tracker settings').first().json;
const staticData = $getWorkflowStaticData('global');
const seen = new Set(Array.isArray(staticData.seenRounds) ? staticData.seenRounds : []);
const clean = (value) => String(value ?? '').replace(/[<>|]/g, '').trim();
const minAmount = Number(settings.minAmountUsd) || 0;

const roundLabels = {
  pre_seed: 'Pre-seed',
  seed: 'Seed',
  series_a: 'Series A',
  series_b: 'Series B',
  series_c: 'Series C',
  series_d_plus: 'Series D+',
  growth: 'Growth',
  strategic: 'Strategic',
  undisclosed: 'Undisclosed',
};

const formatAmount = (amount) => {
  const n = Number(amount);
  if (!n || n <= 0) return 'undisclosed amount';
  if (n >= 1000000000) return '$' + (n / 1000000000).toFixed(1).replace(/\.0$/, '') + 'B';
  if (n >= 1000000) return '$' + Math.round(n / 1000000) + 'M';
  if (n >= 1000) return '$' + Math.round(n / 1000) + 'K';
  return '$' + n.toLocaleString();
};

const normalizeCompany = (name) => clean(name).toLowerCase().replace(/[^a-z0-9]/g, '');
const roundKey = (company, roundType) => normalizeCompany(company) + '|' + String(roundType || 'undisclosed').toLowerCase();

const newRounds = [];
const seenThisRun = new Set();
const sectionsBySector = {};

for (const item of $input.all()) {
  const output = item.json.output || {};
  const sector = clean(output.sector) || 'Funding';
  const rounds = Array.isArray(output.rounds) ? output.rounds : [];

  for (const round of rounds) {
    const company = clean(round.company);
    if (!company) continue;

    const roundType = round.round_type || 'undisclosed';
    const amount = Number(round.amount_usd) || 0;

    if (amount > 0 && amount < minAmount) continue;

    const key = roundKey(company, roundType);
    if (seen.has(key) || seenThisRun.has(key)) continue;

    const url = String(round.url ?? '').trim();
    if (!url) continue;

    seen.add(key);
    seenThisRun.add(key);

    const record = {
      company,
      round_type: roundType,
      amount_usd: amount,
      lead_investors: clean(round.lead_investors),
      sector,
      company_description: clean(round.company_description),
      headline: clean(round.headline) || company + ' funding',
      publisher: clean(round.publisher),
      announced: clean(round.announced),
      url,
    };
    newRounds.push(record);

    const label = roundLabels[roundType] || roundType;
    let line = '• *' + company + '* — ' + label + ', ' + formatAmount(amount);
    if (record.lead_investors) line += ' (lead: ' + record.lead_investors + ')';
    line += ' — <' + url + '|' + record.headline + '>';
    if (record.publisher) line += ' (' + record.publisher + ')';

    if (!sectionsBySector[sector]) sectionsBySector[sector] = [];
    sectionsBySector[sector].push(line);
  }
}

staticData.seenRounds = Array.from(seen).slice(-1000);

const sections = Object.entries(sectionsBySector).map(([sector, lines]) => '*' + sector + '*\n' + lines.join('\n'));
const alertText = ':moneybag: *Funding rounds alert*\n\n' + sections.join('\n\n');

return [{
  json: {
    hasNew: newRounds.length > 0,
    rounds: newRounds,
    alertText,
    slackChannel: settings.slackChannel,
  },
}];

const foundAt = new Date().toISOString();
const input = $input.first().json;
const rounds = Array.isArray(input.rounds) ? input.rounds : [];

if (rounds.length === 0) {
  return [];
}

return rounds.map((round) => ({
  json: {
    found_at: foundAt,
    company: round.company,
    round_type: round.round_type,
    amount_usd: round.amount_usd,
    lead_investors: round.lead_investors,
    sector: round.sector,
    company_description: round.company_description,
    headline: round.headline,
    publisher: round.publisher,
    announced: round.announced,
    url: round.url,
  },
}));
